        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var results = last.results || {};
            var causesFound = results.causesFound || 0;
            var totalScore = results.totalScore || 0;
            var ebitda = results.ebitdaRecovery || 0;

            var performance = 'Developing';
            if (causesFound >= 3 && totalScore > 200) performance = 'Excellent';
            else if (causesFound >= 2 && totalScore > 120) performance = 'Proficient';
            else if (causesFound >= 1 && totalScore > 60) performance = 'Competent';

            var insights = [];
            if (causesFound === 3) {
                insights.push('Outstanding analytical depth! All three root causes identified.');
            } else if (causesFound === 2) {
                insights.push('Good diagnostic ability. One root cause remains hidden.');
            } else if (causesFound === 1) {
                insights.push('Surface-level analysis captured one obvious cause. Deeper investigation needed.');
            } else {
                insights.push('No root causes fully identified. Consider using more structured analytical frameworks.');
            }

            if (ebitda > 60) {
                insights.push('Strong corrective action plan with significant projected EBITDA recovery.');
            } else if (ebitda > 30) {
                insights.push('Moderate action plan. Better alignment between root causes and actions would improve recovery.');
            } else {
                insights.push('Action plan needs stronger connection to identified root causes.');
            }

            return {
                causesFound: causesFound,
                totalScore: totalScore,
                ebitdaRecovery: Math.round(ebitda),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var period = state.currentPeriod || 1;
            if (period === 3 && state.domainState.visitedModules.length < 2) {
                return window.mySimulation.t('hint_explore_more');
            }
            if (period === 5 && state.domainState.causesFound === 0) {
                return window.mySimulation.t('hint_no_causes');
            }
            if (period >= 5 && state.domainState.timeRemaining < 20) {
                return window.mySimulation.t('hint_low_time');
            }
            if (period === 6 && state.domainState.causesFound < 2) {
                return window.mySimulation.t('hint_dig_deeper');
            }
            if (results.timeCost > 0 && state.domainState.timeRemaining < 15) {
                return window.mySimulation.t('hint_time_critical');
            }
            return null;
        }

